function seedStagePixelProps(stage){const stageBack={1:["px_door","px_barredDoor","px_windowGlass","px_statue"],2:["px_door","px_barredDoor","px_windowGlass","px_statue"],3:["px_barredDoor","px_statue","px_bust","px_rocks"],4:["px_windowGlass","px_angelStatue","px_mirror","px_bust"],5:["px_angelStatue","px_windowGlass","px_barredDoor","px_statue"],6:["px_barredDoor","px_windowGlass","px_statue","px_bust"]}[stage]||["px_statue"];const stageMid={1:["px_coffin","px_statue","px_frame","px_bust"],2:["px_windowGlass","px_statue","px_frame","px_bust"],3:["px_rocks","px_statue","px_bust","px_barredDoor"],4:["px_mirror","px_frame","px_bust","px_windowGlass"],5:["px_angelStatue","px_frame","px_bust","px_statue"],6:["px_statue","px_frame","px_bust","px_barredDoor"]}[stage]||["px_statue"];const surfaces=level.solids.filter(s=>s.kind!=="stair"&&s.kind!=="gate"&&s.w>=120).sort((a,b)=>a.x-b.x);function surfaceAt(wx){let best=null;for(const s of surfaces){if(wx>=s.x&&wx<=s.x+s.w&&(!best||s.y<best.y))best=s;}return best;}for(let i=0;i<surfaces.length;i++){const s=surfaces[i],slots=1;for(let j=0;j<slots;j++){const seed=Math.abs(Math.floor(s.x/37+s.y/29+j*11+stage*17)),key=stageMid[seed%stageMid.length],d=propDim(key,s.y<330?.62:.72),wx=s.x+(j+1)*s.w/(slots+1)-d.w/2;if(seed%3===1&&s.y>420)continue;addProp(key,wx,s.y-d.h+5,d.w,d.h,seed%3===0?"back":"mid",seed%3===0?.28:.46,seed%2===0);}}for(let wx=220+stage*41;wx<game.worldWidth;wx+=790){const s=surfaceAt(wx)||{y:GROUND_Y},key=stageBack[Math.abs(Math.floor(wx/83+stage))%stageBack.length],d=propDim(key,s.y<360?.62:.78);addProp(key,wx-d.w/2,s.y-d.h+6,d.w,d.h,"back",.24,Math.floor(wx/790)%2===0);}}
function buildStage(stage){if(stage===1)buildStage1();else if(stage===2)buildStage2();else if(stage===3)buildStage3();else if(stage===4)buildStage4();else if(stage===5)buildStage5();else buildStage6();seedCastleRoute(stage);cleanupPlatformLayout();refreshStairTracks();seedStagePixelProps(stage);game.bossAlive=true;game.stageFlash=1.4;}
function setOverlay(t,l1,l2){overlay.className="overlay";overlay.classList.remove("hidden");overlay.innerHTML=`<h1>${t}</h1><p>${l1}</p><p>${l2}</p>`;}
function hideOverlay(){overlay.classList.add("hidden");}
function stageStartTime(stage){return stage===1?480:stage===2?390:stage===3?370:stage===4?350:stage===5?340:360;}
function stageStartHearts(stage){return stage<=2?14:stage===3?16:stage===4?18:stage===5?20:24;}
function stageMenuText(){const s=clamp(game.selectedStage||1,1,6);return `Stage ${s}: ${STAGE_NAMES[s]||"Unknown"} | ${STAGE_PREVIEWS[s]||""}`;}
function stageMapMarkup(stage){const nodes=Object.keys(MAP_NODES).map((n)=>{const s=Number(n),p=MAP_NODES[s],cls=s<stage?" cleared":s===stage?" active":"";return`<b class="map-node${cls}" style="left:${p.x}%;top:${p.y}%"><span>${s}</span></b>`;}).join("");const lines=Object.keys(MAP_NODES).slice(1).map((n)=>{const s=Number(n),a=MAP_NODES[s-1],b=MAP_NODES[s],x1=a.x,y1=a.y,x2=b.x,y2=b.y,dx=x2-x1,dy=y2-y1,len=Math.hypot(dx,dy),ang=Math.atan2(dy,dx)*180/Math.PI,cls=s<=stage?" lit":"";return`<i class="map-route${cls}" style="left:${x1}%;top:${y1}%;width:${len}%;transform:rotate(${ang}deg)"></i>`;}).join("");return`${lines}${nodes}`;}
