function requestStartGame(fromContinue=false){if(game._startPending)return;const c=fromContinue?loadContinue():null,stage=c?.stage||clamp(game.selectedStage||1,1,6);preloadStageArt(stage);const startAt=performance.now(),poll=()=>{const st=criticalArtStatus(stage),pct=Math.floor(st.ready/Math.max(1,st.total)*100),cmd=overlay.querySelector(".title-command"),sub=overlay.querySelector(".title-subcommand");if(cmd)cmd.textContent=st.complete?"ENTER / START":`LOADING ${pct}%`;if(sub)sub.textContent=st.complete?"NEW RUN":"WARMING CORE ASSETS";if(st.complete||performance.now()-startAt>1800){game._startPending=false;startGame(fromContinue);return;}requestAnimationFrame(poll);};game._startPending=true;poll();}
function loadContinue(){try{const r=localStorage.getItem(SAVE_KEY);if(!r)return null;return JSON.parse(r);}catch{return null;}}
function saveContinue(){if(game.state!=="playing")return;localStorage.setItem(SAVE_KEY,JSON.stringify({stage:game.stage,score:game.score,hp:player.hp,hearts:player.hearts,subWeapon:player.subWeapon,checkpointX:player.checkpointX,timeLeft:Math.max(30,Math.floor(game.timeLeft)),groove:Math.floor(player.groove||0)}));}
