function nearestPoint(px,py,x1,y1,x2,y2){const vx=x2-x1,vy=y2-y1,len2=vx*vx+vy*vy||1;let t=((px-x1)*vx+(py-y1)*vy)/len2;t=clamp(t,0,1);return{x:x1+vx*t,y:y1+vy*t,t};}
function stairUpDir(s){return s.y2<s.y1?1:-1;}
