function stairInputAxis(st){let axis=(input.up?1:0)-(input.down?1:0);if(!axis){const h=(input.right?1:0)-(input.left?1:0);if(h){const upX=Math.sign((st.x2-st.x1)*st.upDir)||1;axis=h===upX?1:-1;}}return axis;}
