if(player.dashTimer>0&&aabb(player,e)&&e.lastDashId!==player.dashId){e.lastDashId=player.dashId;hurtEnemy(e,boss?2:3,player.facing*180);spawnParticles(e.x+e.w/2,e.y+e.h/2,"#bfe7ff",10);playSfx("enemyHit",.48,1.08,.04);addShake(6,.09);}
if(e.type==="zombie"){if(typeof e.baseX!=="number")e.baseX=e.x;e.x+=e.vx*edt*ENEMY_PACE*eliteMul;if(e.x<e.baseX-70||e.x>e.baseX+70)e.vx*=-1;}
else if(e.type==="skeleton"){if(typeof e.baseX!=="number")e.baseX=e.x;e.x+=e.vx*edt*ENEMY_PACE*eliteMul;if(e.x<e.baseX-130||e.x>e.baseX+130)e.vx*=-1;e.cooldown-=edt*eliteMul;if(e.cooldown<=0&&Math.abs(player.x-e.x)<420){e.cooldown=1.55/eliteMul;const d=player.x<e.x?-1:1;level.enemyShots.push({x:e.x+e.w/2,y:e.y+12,w:10,h:10,vx:d*200*eliteMul,vy:-210,gravity:780,type:"bone"});}}
