function spawnParticles(x,y,color,amount){const budget=Math.max(0,MAX_PARTICLES-level.particles.length),scaled=Math.min(budget,Math.ceil(amount*fxScale()));for(let i=0;i<scaled;i++)level.particles.push({x,y,vx:(Math.random()-.5)*220,vy:(Math.random()-1)*220,life:.4+Math.random()*.3,size:2+Math.random()*2,color});}
function updateParticles(dt){for(const p of level.particles){p.vy+=680*dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.life-=dt;}level.particles=level.particles.filter(p=>p.life>0);if(level.particles.length>MAX_PARTICLES)level.particles.splice(0,level.particles.length-MAX_PARTICLES);}
function updateGame(dt){if(!game.testMode){game.timeLeft-=dt;if(game.timeLeft<=0){game.timeLeft=0;playerDamage(99,0);}}else{player.hp=player.maxHp;player.hearts=99;}if(!game.testMode&&player.invuln<=0&&player.regenTimer>=REGEN_COOLDOWN){if(player.hp<player.maxHp){player.hp=clamp(player.hp+1,0,player.maxHp);player.regenTimer=0;spawnParticles(player.x+player.w/2,player.y+8,"#b8ffd3",5);playTone(540,.04,"triangle",.028);}else if(player.guard<player.maxGuard){player.guard++;player.regenTimer=0;spawnParticles(player.x+player.w/2,player.y+8,"#b8e8ff",6);playTone(880,.04,"triangle",.03);}}if(game.comboTimer>0){game.comboTimer-=dt;if(game.comboTimer<=0)game.combo=0;}if(game.shakeTime>0){game.shakeTime-=dt;if(game.shakeTime<=0){game.shakeTime=0;game.shakePower=0;}else game.shakePower=Math.max(0,game.shakePower-dt*42);}if(game.stageFlash>0)game.stageFlash-=dt;
if(!game.testMode&&game.stage===6){if(!game.stage6BossPrep&&player.x>8580){game.stage6BossPrep=true;player.hp=clamp(player.hp+8,0,player.maxHp);player.hearts=clamp(player.hearts+12,0,99);player.guard=clamp(player.guard+2,0,player.maxGuard);game.timeLeft+=35;spawnParticles(player.x+player.w/2,player.y+6,"#ffdcb8",16);playTone(740,.08,"triangle",.04);}game.stage6AidCd-=dt;if(game.stage6AidCd<=0){game.stage6AidCd=game.finalEasy?5.5:7;player.hp=clamp(player.hp+1,0,player.maxHp);player.hearts=clamp(player.hearts+1,0,99);if(player.guard<player.maxGuard&&Math.random()<.5)player.guard++;spawnParticles(player.x+player.w/2,player.y+6,"#ffdcb8",7);playTone(600,.05,"triangle",.03);}}
updatePlayer(dt);updateMapRooms();updateStageZones(dt);updateCandles();updatePickups(dt);updateEnemies(dt);updateBossArena(dt);updateProjectiles(dt);updateStage4Encounter();updateParticles(dt);if(game.tick%30===0)syncBgmToBoss();const target=clamp(player.x-canvas.width*.42,0,game.worldWidth-canvas.width);game.cameraX=clamp(snap(lerp(game.cameraX,target,.12)),0,Math.max(0,game.worldWidth-canvas.width));
if(!game.bossAlive&&player.x>level.exitX){if(game.stage<6){game.stage++;game.stage4EventActive=false;game.stage4EventDone=game.stage!==4;game.arenaCd=0;game.arenaPattern="";game.stage6AidCd=6;game.timeLeft=Math.max(180,Math.floor(game.timeLeft))+130;preloadStageArt(game.stage);buildStage(game.stage);Object.assign(player,{x:110,y:340,vx:0,vy:0,checkpointX:100,onStair:false,stairRef:null,stairIndex:0,stairTargetIndex:0,stairTravel:1,stairMoving:false,stairDetachTimer:0});game.cameraX=0;saveContinue();stopMusic();playSfx("gate",.5,1,.45);showStageTransition(game.stage);game.state="intermission";return;}updateBest();clearContinue();game.stage6Fails=0;game.state="win";setOverlay("STAGE CLEARED","Alle 6 Stages geschafft","Enter neuer Run | 1-6 Direktstart | <-/-> Stage");stopMusic();playTone(880,.18,"triangle",.08);}saveContinue();}
function drawCoverParallax(key,parallax,alpha){const img=getImg(key);if(!img.complete||!img.naturalWidth)return;const scale=Math.max(canvas.width/img.naturalWidth,canvas.height/img.naturalHeight),dw=Math.ceil(img.naturalWidth*scale),dh=Math.ceil(img.naturalHeight*scale),y=snap((canvas.height-dh)*.5),cam=snap(game.cameraX*parallax),off=-posMod(cam,dw);ctx.save();ctx.imageSmoothingEnabled=false;ctx.globalAlpha=alpha;for(let x=off-dw;x<canvas.width+dw;x+=dw)ctx.drawImage(img,snap(x),y,dw,dh);ctx.restore();}
function drawBgTile(key,x,y,w,h,alpha=.38){const img=getTile(key);if(!img.complete||!img.naturalWidth)return;ctx.save();ctx.imageSmoothingEnabled=false;ctx.globalAlpha=alpha;ctx.drawImage(img,snap(x),snap(y),Math.ceil(w),Math.ceil(h));ctx.restore();}
function drawPixelImage(key,x,y,w,h,alpha=1,flip=false){const img=getPixel(key);if(!img||!img.complete||!img.naturalWidth)return false;x=snap(x);y=snap(y);w=Math.ceil(w);h=Math.ceil(h);ctx.save();ctx.imageSmoothingEnabled=false;ctx.globalAlpha*=alpha;if(flip){ctx.translate(x+snap(w/2),0);ctx.scale(-1,1);ctx.drawImage(img,-snap(w/2),y,w,h);}else ctx.drawImage(img,x,y,w,h);ctx.restore();return true;}
function drawPixelRotated(key,cx,cy,w,h,angle=0,alpha=1){const img=getPixel(key);if(!img||!img.complete||!img.naturalWidth)return false;ctx.save();ctx.imageSmoothingEnabled=false;ctx.globalAlpha*=alpha;ctx.translate(cx,cy);ctx.rotate(angle);ctx.drawImage(img,-w/2,-h/2,w,h);ctx.restore();return true;}
function drawPixelProps(layer){if(!level.props)return;for(const p of level.props){if(p.layer!==layer||!isRectVisible(p.x,p.y,p.w,p.h))continue;drawPixelImage(p.key,p.x-game.cameraX,p.y,p.w,p.h,p.alpha,p.flip);}}
const TREE_ARCH_TILE={blank:0,trunk:1,branchLeft:2,branchRight:3,leafCore:4,leafHighlight:5,leafLeft:6,leafRight:7,roots:8,pillar:9,base:10,cap:11,archLeft:12,archMid:13,archRight:14,shadow:15,bars:16,vine:17};
function drawTreeArchTile(idx,x,y,w,h){const img=getSheet("treeArch");if(!img||!img.complete||!img.naturalWidth)return false;const size=32,cols=8,sx=(idx%cols)*size,sy=Math.floor(idx/cols)*size;ctx.drawImage(img,sx,sy,size,size,snap(x),snap(y),Math.ceil(w),Math.ceil(h));return true;}
function drawForestTreeTilemap(x,y,w,h){const img=getSheet("treeArch");if(!img||!img.complete||!img.naturalWidth)return false;const cw=w/5,ch=h/8,layout=[
[-1,TREE_ARCH_TILE.leafLeft,TREE_ARCH_TILE.leafHighlight,TREE_ARCH_TILE.leafRight,-1],
[TREE_ARCH_TILE.leafLeft,TREE_ARCH_TILE.leafCore,TREE_ARCH_TILE.leafHighlight,TREE_ARCH_TILE.leafCore,TREE_ARCH_TILE.leafRight],
[TREE_ARCH_TILE.leafCore,TREE_ARCH_TILE.leafHighlight,TREE_ARCH_TILE.leafCore,TREE_ARCH_TILE.leafHighlight,TREE_ARCH_TILE.leafCore],
[-1,TREE_ARCH_TILE.leafLeft,TREE_ARCH_TILE.branchLeft,TREE_ARCH_TILE.branchRight,-1],
[-1,TREE_ARCH_TILE.leafCore,TREE_ARCH_TILE.trunk,TREE_ARCH_TILE.leafHighlight,-1],
[-1,-1,TREE_ARCH_TILE.trunk,-1,-1],
[-1,-1,TREE_ARCH_TILE.trunk,-1,-1],
[-1,-1,TREE_ARCH_TILE.roots,-1,-1]
];let tiles=0;for(let r=0;r<layout.length;r++){for(let c=0;c<layout[r].length;c++){const id=layout[r][c];if(id<0)continue;if(drawTreeArchTile(id,x+c*cw,y+r*ch,cw+2,ch+2))tiles++;}}game._treeArchTilemapDebug=game._treeArchTilemapDebug||{treeTiles:0,archTiles:0,sheetLoaded:false};game._treeArchTilemapDebug.treeTiles+=tiles;game._treeArchTilemapDebug.sheetLoaded=true;return tiles>0;}
function drawArchTilemap(type,x,y,w,h){const img=getSheet("treeArch");if(!img||!img.complete||!img.naturalWidth)return false;const cols=8,rows=8,cw=w/cols,ch=h/rows,gate=type==="gardenGate";let tiles=0;const tile=(id,c,r,ww=1,hh=1)=>{if(drawTreeArchTile(id,x+c*cw,y+r*ch,cw*ww+1,ch*hh+1))tiles++;};
for(let c=1;c<=6;c++)tile(c===1?TREE_ARCH_TILE.archLeft:c===6?TREE_ARCH_TILE.archRight:c===3||c===4?TREE_ARCH_TILE.archMid:TREE_ARCH_TILE.cap,c,1);
tile(TREE_ARCH_TILE.archLeft,1,2);tile(TREE_ARCH_TILE.archMid,2,2);tile(TREE_ARCH_TILE.shadow,3,2,2,1);tile(TREE_ARCH_TILE.archMid,5,2);tile(TREE_ARCH_TILE.archRight,6,2);
for(let r=3;r<=6;r++){tile(TREE_ARCH_TILE.pillar,1,r);tile(TREE_ARCH_TILE.pillar,6,r);if(gate){tile(TREE_ARCH_TILE.bars,3,r);tile(TREE_ARCH_TILE.bars,4,r);}else if(r===4||r===5){tile(TREE_ARCH_TILE.vine,r===4?2:5,r);}}
tile(TREE_ARCH_TILE.base,1,7);tile(TREE_ARCH_TILE.base,6,7);tile(TREE_ARCH_TILE.cap,0,2);tile(TREE_ARCH_TILE.cap,7,2);if(!gate){tile(TREE_ARCH_TILE.vine,1,3);tile(TREE_ARCH_TILE.vine,6,3);}
game._treeArchTilemapDebug=game._treeArchTilemapDebug||{treeTiles:0,archTiles:0,sheetLoaded:false};game._treeArchTilemapDebug.archTiles+=tiles;game._treeArchTilemapDebug.sheetLoaded=true;return tiles>0;}
function bushFenceDebug(){const dbg=game._bushFenceTilemapDebug||(game._bushFenceTilemapDebug={bushTiles:0,fenceTiles:0,latticeTiles:0,sheetLoaded:false});dbg.sheetLoaded=true;return dbg;}
