function drawTileFill(group,x,y,w,h,step=96,worldX=x,worldY=y){let used=false;x=snap(x);y=snap(y);w=Math.ceil(w);h=Math.ceil(h);const startCol=Math.floor((worldX-2)/step),endCol=Math.ceil((worldX+w+2)/step),startRow=Math.floor((worldY-2)/step),endRow=Math.ceil((worldY+h+2)/step);ctx.save();ctx.beginPath();ctx.rect(x,y,w,h);ctx.clip();ctx.imageSmoothingEnabled=false;for(let col=startCol;col<=endCol;col++){for(let row=startRow;row<=endRow;row++){const img=getTile(group[posMod(col+row,group.length)]);if(img.complete&&img.naturalWidth>0){ctx.drawImage(img,snap(col*step-game.cameraX),snap(row*step),step+2,step+2);used=true;}}}ctx.restore();return used;}
