function drawStairStepBlock(x,y,w,h,seed=0,alpha=.9,faceH=10){x=snap(x);y=snap(y);w=Math.ceil(w);faceH=clamp(Math.ceil(faceH),8,12);ctx.save();ctx.imageSmoothingEnabled=false;ctx.globalAlpha=alpha;ctx.fillStyle="rgba(0,0,0,.24)";ctx.fillRect(x+5,y+faceH+8,w-10,4);ctx.fillStyle="#17181b";ctx.fillRect(x+2,y+7,w-4,faceH);ctx.fillStyle="#333534";ctx.fillRect(x+5,y+9,w-10,Math.max(4,faceH-3));ctx.fillStyle="rgba(0,0,0,.25)";ctx.fillRect(x+7,y+faceH+5,w-14,2);ctx.fillStyle="#1d1c1d";ctx.fillRect(x+1,y+5,w-2,7);ctx.fillStyle="#4f4d48";ctx.fillRect(x+3,y+3,w-6,7);ctx.fillStyle="#b09b6c";ctx.fillRect(x+5,y+1,w-10,3);ctx.fillStyle="rgba(255,232,166,.4)";ctx.fillRect(x+7,y+1,Math.max(8,w-14),2);ctx.fillStyle="rgba(0,0,0,.34)";ctx.fillRect(x+6,y+8,Math.max(8,w-12),3);ctx.restore();}
function drawStairStep(x,y,w,h){drawStairStepBlock(x,y,w,h,Math.floor((x+y)/48));}
