function drawStairRun(st){const steps=stairSteps(st).slice().sort((a,b)=>a.x-b.x||a.y-b.y),last=steps.length-1;ctx.save();ctx.imageSmoothingEnabled=false;ctx.fillStyle="rgba(20,16,15,.45)";for(let i=0;i<last;i++){const a=steps[i],b=steps[i+1];if(!isRectVisible(Math.min(a.x,b.x)-12,Math.min(a.y,b.y)-14,Math.abs(b.x-a.x)+90,48))continue;const x=snap(Math.min(a.x,b.x)-game.cameraX+24),y=snap(Math.max(a.y,b.y)+8),w=Math.max(18,snap(Math.abs(b.x-a.x)+18));ctx.fillRect(x,y,w,5);}for(let i=0;i<steps.length;i++){const s=steps[i];if(!isRectVisible(s.x-12,s.y-14,s.w+24,s.h+28))continue;const x=snap(s.x-game.cameraX-3),y=snap(s.y-2),w=Math.max(44,Math.ceil(s.w+6)),end=i===0||i===last;drawStairStepBlock(x,y,w,8,i+game.stage*3,end?.94:.88,10);}for(let i=0;i<last;i++){const a=steps[i],b=steps[i+1],upper=a.y<b.y?a:b,lower=a.y<b.y?b:a;if(!isRectVisible(Math.min(a.x,b.x)-12,upper.y-14,Math.abs(b.x-a.x)+90,Math.abs(b.y-a.y)+36))continue;const x=snap((a.x+b.x)/2-game.cameraX+20),y=snap(upper.y+7),h=Math.abs(b.y-a.y)+11;drawStairRiser(x,y,h,.64);}ctx.restore();}
function drawBrick(x,y,w,h,kind,worldX=x){if(kind==="stair")return;x=snap(x);y=snap(y);w=Math.ceil(w);h=Math.ceil(h);const gateLike=kind==="gate"||kind==="seal",group=TILE_FILES[kind]||(gateLike?TILE_FILES.gate:TILE_FILES.stone),step=96,base=kind==="boss"?"#46313b":gateLike?"#27384c":kind==="floor"?"#312d2f":kind==="gothic"?"#303842":kind==="crypt"?"#3d3841":kind==="flesh"?"#4e2639":"#3a3633";ctx.fillStyle=base;ctx.fillRect(x,y,w,h);drawTileFill(group,x,y,w,h,step,worldX,y);drawPlatformZisel(x,y,w,h,kind,worldX);if(gateLike){const g=getTile("tile_gate");if(g.complete)ctx.drawImage(g,x,snap(y-h*.35),Math.max(42,w),Math.ceil(h*1.35));if(kind==="seal"){ctx.save();ctx.globalCompositeOperation="lighter";ctx.fillStyle="rgba(120,220,255,.22)";ctx.beginPath();ctx.arc(x+w/2,y+h*.42,Math.max(10,w*.72),0,Math.PI*2);ctx.fill();ctx.restore();}}}
