function enemySheetMeta(e){if(isBoss(e)){const row=BOSS_SHEET_ROWS[e.type];return row===undefined?null:{sheet:"boss",row,fw:300,fh:240,frames:3};}const row=ENEMY_SHEET_ROWS[e.type];return row===undefined?null:{sheet:"enemy",row,fw:128,fh:176,frames:4};}
