function drawEnemyFallbackSprite(e,x){const spr=getSprite(e.type);if(!spr||!spr.complete||!spr.naturalWidth)return false;const boss=isBoss(e),dh=e.h+(boss?38:22),dw=Math.max(e.w+(boss?38:18),dh*(spr.naturalWidth/Math.max(1,spr.naturalHeight))),flip=!boss&&(e.vx||0)<0;ctx.save();if(e.type==="phantom")ctx.globalAlpha=e.elite?.82:.68;if(flip){ctx.translate(x+e.w/2,0);ctx.scale(-1,1);ctx.drawImage(spr,-dw/2,e.y+e.h-dh+8,dw,dh);}else ctx.drawImage(spr,x+e.w/2-dw/2,e.y+e.h-dh+8,dw,dh);ctx.restore();return true;}
