function playTone(freq,dur,type,g){if(!audioCtx||SYNTH_SFX_MASTER<=0)return;ensureAudioGraph();const now=audioCtx.currentTime,osc=audioCtx.createOscillator(),gain=audioCtx.createGain();osc.type=type;osc.frequency.setValueAtTime(freq,now);gain.gain.setValueAtTime(g,now);gain.gain.exponentialRampToValueAtTime(.0001,now+dur);osc.connect(gain);gain.connect(_sfxGain||audioCtx.destination);osc.start(now);osc.stop(now+dur);}
function playNoise(dur,g){if(!audioCtx||SYNTH_SFX_MASTER<=0)return;ensureAudioGraph();const b=audioCtx.createBuffer(1,Math.floor(audioCtx.sampleRate*dur),audioCtx.sampleRate),d=b.getChannelData(0);for(let i=0;i<d.length;i++)d[i]=(Math.random()*2-1)*.18;const src=audioCtx.createBufferSource(),gain=audioCtx.createGain();src.buffer=b;gain.gain.value=g*.48;gain.gain.exponentialRampToValueAtTime(.0001,audioCtx.currentTime+dur);src.connect(gain);gain.connect(_sfxGain||audioCtx.destination);src.start();src.stop(audioCtx.currentTime+dur);}
function playKick(dur,g){if(!audioCtx||MUSIC_SYNTH_MASTER<=0)return;ensureAudioGraph();const now=audioCtx.currentTime,osc=audioCtx.createOscillator(),gain=audioCtx.createGain();osc.type="sine";osc.frequency.setValueAtTime(110,now);osc.frequency.exponentialRampToValueAtTime(48,now+dur);gain.gain.setValueAtTime(g*.68,now);gain.gain.exponentialRampToValueAtTime(.0001,now+dur);osc.connect(gain);gain.connect(_musicGain||audioCtx.destination);osc.start(now);osc.stop(now+dur);}
function playPad(freq,dur,g){if(!audioCtx||MUSIC_SYNTH_MASTER<=0)return;ensureAudioGraph();const now=audioCtx.currentTime,osc=audioCtx.createOscillator(),gain=audioCtx.createGain();osc.type="triangle";osc.frequency.setValueAtTime(freq,now);gain.gain.setValueAtTime(g,now);gain.gain.exponentialRampToValueAtTime(.0001,now+dur);osc.connect(gain);gain.connect(_musicGain||audioCtx.destination);osc.start(now);osc.stop(now+dur);}
