function startMusic(){if(!audioCtx)audioCtx=new (window.AudioContext||window.webkitAudioContext)();ensureAudioGraph();if(audioCtx.state==="suspended")audioCtx.resume?.();preloadSfx();playBgm(currentBgmKey());if(musicTimer)return;musicTimer=setInterval(()=>{if(game.state!=="playing")return;syncBgmToBoss();if(!_curBgm||_curBgm.paused||_bgmBlocked){const now=performance.now();if(now-_lastBgmAttempt>850)playBgm(currentBgmKey(),false);}},850);}
function stopMusic(){if(musicTimer){clearInterval(musicTimer);musicTimer=null;}stopBgm();} function restartMusic(){stopMusic();startMusic();}
function syncBgmToBoss(){if(game.state!=="playing")return;const want=currentBgmKey();if(_curBgmGroup!==String(want))playBgm(want);}
function updateAutoQuality(){const verySlow=game.frameAvg>.026||game.fps<42,slow=game.frameAvg>.0205||game.fps<54,smooth=game.frameAvg<.0167&&game.fps>58;if(verySlow){game.perfHold=110;game.fxRecover=0;}else if(slow){game.perfHold=Math.max(game.perfHold,70);game.fxRecover=0;}else if(game.perfHold>0){game.perfHold--;game.fxRecover=0;}else if(smooth)game.fxRecover=Math.min(240,(game.fxRecover||0)+1);else game.fxRecover=0;game.perfMode=game.perfHold>0?1:0;const target=game.perfHold>95?0:game.perfHold>0?1:game.fxRecover>180?2:1;if(game.fxQuality!==target){game.fxQuality=target;game.qualitySwitches=(game.qualitySwitches||0)+1;}}
function loop(ts){if(!lastTime)lastTime=ts;const dt=Math.min(.033,(ts-lastTime)/1000);lastTime=ts;game.tick++;game.frameAvg=lerp(game.frameAvg,dt,.08);game.fps=Math.round(1/Math.max(.001,game.frameAvg));if(game.qualityMode==="auto")updateAutoQuality();else{game.perfHold=0;game.perfMode=0;game.fxRecover=0;if(game.qualityMode==="high")game.fxQuality=2;else if(game.qualityMode==="med")game.fxQuality=1;else game.fxQuality=0;}if(game.state==="playing")updateGame(dt);render();if(game.tick%2===0||game.state!=="playing")updateHud();input.jumpQueued=false;input.dashQueued=false;input.specialQueued=false;input.moonwalkQueued=false;input.danceQueued=false;requestAnimationFrame(loop);}
function bootAudio(){if(!audioCtx)audioCtx=new (window.AudioContext||window.webkitAudioContext)();ensureAudioGraph();const resumed=audioCtx.state==="suspended"?audioCtx.resume?.():null;preloadSfx();if(resumed&&resumed.then)resumed.then(()=>retryBgm()).catch(()=>{});else retryBgm();}
function fullscreenElement(){return document.fullscreenElement||document.webkitFullscreenElement||document.msFullscreenElement||null;}
function updateFullscreenToggle(){const active=!!fullscreenElement()||document.body.classList.contains("mobile-pseudo-fullscreen");document.body.classList.toggle("fullscreen-active",active);if(fullscreenToggle){fullscreenToggle.setAttribute("aria-pressed",active?"true":"false");fullscreenToggle.classList.toggle("is-active",active);fullscreenToggle.title=active?"Exit fullscreen":"Enter fullscreen";}}
function exitGameFullscreen(){document.body.classList.remove("mobile-pseudo-fullscreen");const exit=document.exitFullscreen||document.webkitExitFullscreen||document.msExitFullscreen;if(fullscreenElement()&&exit){const p=exit.call(document);if(p&&p.catch)p.catch(()=>{});}updateFullscreenToggle();}
function requestGameFullscreen(){const el=document.querySelector(".frame")||document.documentElement;if(fullscreenElement()||document.body.classList.contains("mobile-pseudo-fullscreen")){exitGameFullscreen();return;}const req=el.requestFullscreen||el.webkitRequestFullscreen||el.msRequestFullscreen;if(req){const p=req.call(el);if(p&&p.catch)p.catch(()=>{if(document.body.classList.contains("touch-layout"))document.body.classList.add("mobile-pseudo-fullscreen");updateFullscreenToggle();});setTimeout(updateFullscreenToggle,120);return;}if(document.body.classList.contains("touch-layout"))document.body.classList.add("mobile-pseudo-fullscreen");updateFullscreenToggle();}
function updateTouchLayout(){const coarse=matchMedia("(pointer: coarse)").matches||matchMedia("(hover: none)").matches||navigator.maxTouchPoints>0,wide=Math.max(innerWidth,innerHeight),narrow=Math.min(innerWidth,innerHeight),desktopMode=wide>=1100&&narrow>=700,mobile=coarse&&!desktopMode;document.body.classList.toggle("touch-layout",mobile);if(!mobile)document.body.classList.remove("mobile-pseudo-fullscreen");updateFullscreenToggle();}
function handleKeyDown(e){const key=e.key.toLowerCase(),menu=game.state==="title"||game.state==="gameover"||game.state==="win";bootAudio();if(["ArrowLeft","ArrowRight","ArrowUp","ArrowDown"," "].includes(e.key)||["a","d","w","s","j","k","l","u","z","x","m"].includes(key))e.preventDefault();if(game.state==="intermission"){e.preventDefault();resumeIntermission();return;}if(menu&&(e.key==="ArrowLeft"||e.key==="ArrowRight")){game.selectedStage=e.key==="ArrowLeft"?(game.selectedStage<=1?6:game.selectedStage-1):(game.selectedStage>=6?1:game.selectedStage+1);if(game.state==="title")showMainMenuOverlay();else setOverlay("STAGE SELECT",stageMenuText(),"Enter Start | C Continue | 1-6 Direktstart | Z/X/M im Spiel");return;}if(/^[1-6]$/.test(e.key)&&menu){game.selectedStage=Number(e.key);requestStartGame(false);return;}if(e.key==="Enter"){if(menu)requestStartGame(false);return;}if(key==="c"&&(game.state==="title"||game.state==="gameover")){const s=loadContinue();if(s)requestStartGame(true);return;}if(key==="t"){game.testMode=!game.testMode;if(game.testMode){player.hp=player.maxHp;player.hearts=99;player.specialCharge=100;player.groove=100;if(game.state!=="playing")setOverlay("TEST MODE ON","Unendlich HP, Ammo und Groove aktiv","T aus | Enter Start | 1-6 Direktstart");}else if(game.state==="title")showMainMenuOverlay();return;}if(key==="q"){game.qualityMode=game.qualityMode==="auto"?"high":game.qualityMode==="high"?"med":game.qualityMode==="med"?"low":"auto";if(game.state!=="playing")setOverlay("GRAPHICS MODE",`Quality: ${game.qualityMode.toUpperCase()}`,`${stageMenuText()} | Q: Auto/High/Med/Low`);return;}if(key==="f"){game.finalEasy=!game.finalEasy;if(game.state!=="playing")setOverlay("FINAL EASY",game.finalEasy?"Stage 6 extra vereinfacht":"Stage 6 normaler",`${stageMenuText()} | F toggelt | 1-6 Start`);return;}if(key==="m"&&game.state==="playing"){nextBgmTrack();return;}if(e.key==="ArrowLeft"||key==="a")input.left=true;if(e.key==="ArrowRight"||key==="d")input.right=true;if(e.key==="ArrowUp"||key==="w")input.up=true;if(e.key==="ArrowDown"||key==="s")input.down=true;if(e.key==="ArrowUp"||e.code==="Space"){if(!input.jumpHeld)input.jumpQueued=true;input.jumpHeld=true;}if(key==="j")input.whip=true;if(key==="k")input.sub=true;if(key==="l")input.dashQueued=true;if(key==="u")input.specialQueued=true;if(key==="z")input.moonwalkQueued=true;if(key==="x")input.danceQueued=true;}
function handleKeyUp(e){const key=e.key.toLowerCase();if(e.key==="ArrowLeft"||key==="a")input.left=false;if(e.key==="ArrowRight"||key==="d")input.right=false;if(e.key==="ArrowUp"||key==="w")input.up=false;if(e.key==="ArrowDown"||key==="s")input.down=false;if(e.key==="ArrowUp"||e.code==="Space")input.jumpHeld=false;if(key==="j")input.whip=false;if(key==="k")input.sub=false;}
function menuActive(){return game.state==="title"||game.state==="gameover"||game.state==="win";}
function resumeIntermission(){game.state="playing";hideOverlay();playSfx("gate",.42,1,.45);restartMusic();}
function runTouchCommand(action,pressed){if(pressed)bootAudio();if(action==="fullscreen"){if(pressed)requestGameFullscreen();return;}if(pressed&&game.state==="intermission"){resumeIntermission();return;}if(action==="start"){if(pressed){if(menuActive())requestStartGame(false);}return;}if(action==="continue"){if(pressed&&(game.state==="title"||game.state==="gameover")){const s=loadContinue();if(s)requestStartGame(true);}return;}if(action==="music"){if(pressed&&game.state==="playing")nextBgmTrack();return;}if(action==="left"){input.left=pressed;return;}if(action==="right"){input.right=pressed;return;}if(action==="up"){input.up=pressed;return;}if(action==="down"){input.down=pressed;return;}if(action==="jump"){if(pressed&&!input.jumpHeld)input.jumpQueued=true;input.jumpHeld=pressed;return;}if(action==="whip"){input.whip=pressed;return;}if(action==="sub"){input.sub=pressed;return;}if(!pressed)return;if(action==="dash")input.dashQueued=true;else if(action==="moonwalk")input.moonwalkQueued=true;else if(action==="dance")input.danceQueued=true;else if(action==="special")input.specialQueued=true;}
function bindTouchControls(){if(!touchControls)return;const active=new Map(),finish=(id)=>{const held=active.get(id);if(!held)return;active.delete(id);held.el.classList.remove("is-down");runTouchCommand(held.action,false);};touchControls.addEventListener("pointerdown",(e)=>{const el=e.target.closest("[data-touch]");if(!el)return;e.preventDefault();e.stopPropagation();const action=el.dataset.touch;active.set(e.pointerId,{action,el});el.classList.add("is-down");try{el.setPointerCapture(e.pointerId);}catch(_){}runTouchCommand(action,true);},{passive:false});["pointerup","pointercancel","lostpointercapture"].forEach(type=>touchControls.addEventListener(type,(e)=>{e.preventDefault();e.stopPropagation();finish(e.pointerId);},{passive:false}));touchControls.addEventListener("contextmenu",(e)=>e.preventDefault());}
